import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    directory = Path(directory_path)

    if not directory.exists() or not directory.is_dir():
        return {}

    result = {}

    for file_name in glob.glob(str(directory / "*")):
        file_path = Path(file_name)
        if not file_path.is_file():
            continue

        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        matches = []
        for match in re.finditer(regex_pattern, content):
            groups = match.groups()
            if groups:
                captured = next((g for g in groups if g is not None), None)
                matches.append(captured if captured is not None else match.group(0))
            else:
                token = match.group(0)
                if len(token) >= 2 and token.startswith("(") and token.endswith(")"):
                    matches.append(token[1:-1])
                else:
                    matches.append(token)

        result[file_path.name] = matches

    return result
